```

Call `configure_auth(app)` from your app factory. Keep the secret stable across application restarts and never commit it to Git.

## 2. Update your existing user model

Do not create a second user model or database connection. Add `UserMixin` and a password-verification method to your existing model:

```python
from flask_login import UserMixin

# Use your existing initialized Flask-Argon2 instance.
from app.extensions import argon2, db


class User(UserMixin, db.Model):
    __tablename__ = "users"

    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.Text, nullable=False)

    def set_password(self, password):
        self.password_hash = argon2.hash_password(password)

    def check_password(self, password):
        return argon2.verify_password(self.password_hash, password)
```

Your registration route should call `user.set_password(password)` before saving the user. **Never compare a submitted password directly with `password_hash`.**

If your database still contains older bcrypt hashes, retain a compatible verification/migration path; Argon2 verification alone will not authenticate those accounts.

## 3. Add the authentication blueprint

This uses Flask-WTF validation and CSRF protection. The imports below assume your extensions and model are available in the indicated modules.

```python
from flask import (
    Blueprint, current_app, flash, redirect,
    render_template, session, url_for,
)
from flask_login import (
    current_user, login_required, login_user, logout_user,
)
from flask_wtf import FlaskForm
from sqlalchemy.exc import SQLAlchemyError
from wtforms import PasswordField, StringField, SubmitField
from wtforms.validators import InputRequired, Length

from app.extensions import db, login_manager
from app.models import User

auth = Blueprint("auth", __name__)


class LoginForm(FlaskForm):
    username = StringField(
        "Username",
        validators=[InputRequired(), Length(max=80)],
    )
    password = PasswordField(
        "Password",
        validators=[InputRequired(), Length(max=1024)],
    )
    submit = SubmitField("Log in")


class LogoutForm(FlaskForm):
    submit = SubmitField("Log out")


@login_manager.user_loader
def load_user(user_id):
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


@auth.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("auth.account"))

    form = LoginForm()

    if form.validate_on_submit():
        try:
            user = db.session.execute(
                db.select(User).where(
                    User.username == form.username.data.strip()
                )
            ).scalar_one_or_none()

            valid = user is not None and user.check_password(
                form.password.data
            )
        except SQLAlchemyError:
            db.session.rollback()
            current_app.logger.exception("Login database failure")
            return "Login is temporarily unavailable.", 503

        if valid:
            session.clear()
            login_user(user, remember=False)
            session.permanent = True
            return redirect(url_for("auth.account"))

        flash("Invalid username or password.", "error")
        return render_template("login.html", form=form), 401

    return render_template("login.html", form=form)


@auth.get("/account")
@login_required
def account():
    return render_template("account.html", logout_form=LogoutForm())


@auth.post("/logout")
@login_required
def logout():
    form = LogoutForm()
    if not form.validate_on_submit():
        return "Invalid logout request.", 400

    logout_user()
    session.clear()
    return redirect(url_for("auth.login"))
```

Register it in your app factory:

```python
